#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include <assert.h>

/* ============================================================================
 * Platform & Architecture Abstraction
 * ============================================================================
 * ARMv8-A (AArch64) Bare-Metal MMIO Access Primitives.
 * Assumes Device-nGnRnE memory type (standard for peripherals).
 * Requires explicit Data Memory Barriers (DMB) for ordering.
 * ============================================================================ */

#if defined(__aarch64__)
    #define ARCH_ARM64 1
#elif defined(__arm__)
    #define ARCH_ARM32 1
#else
    #error "Unsupported architecture: ARMv8-A (AArch64) required."
#endif

/* Compiler Barrier: Prevents compiler reordering. */
static inline void compiler_barrier(void) {
    __asm__ volatile ("" ::: "memory");
}

/* Hardware Memory Barrier: DMB ISH (Inner Shareable Domain). */
static inline void dmb_ish(void) {
#if ARCH_ARM64
    __asm__ volatile ("dmb ish" ::: "memory");
#elif ARCH_ARM32
    __asm__ volatile ("dmb ish" ::: "memory");
#endif
}

/* Yield Hint: Polite busy-wait (WFE/YIELD). */
static inline void cpu_yield(void) {
#if ARCH_ARM64
    __asm__ volatile ("yield" ::: "memory");
#elif ARCH_ARM32
    __asm__ volatile ("wfe" ::: "memory");
#endif
}

/* ============================================================================
 * Register Map Definition (Base: 0x4000_1000)
 * ============================================================================
 * Alignment: 4-byte aligned accesses required for 32-bit registers.
 * Volatile: Mandatory for MMIO.
 * ============================================================================ */

#define PERIPH_BASE_ADDR    (UINT64_C(0x40001000))
#define REG_CTRL_OFFSET     (0x00)
#define REG_STATUS_OFFSET   (0x04)
#define REG_DATA_OFFSET     (0x08)
#define REG_IRQ_MASK_OFFSET (0x0C)

/* Register Bit Definitions (Example Semantics) */
/* CTRL */
#define CTRL_EN_BIT         (UINT32_C(1) << 0)   /* Enable */
#define CTRL_RST_BIT        (UINT32_C(1) << 1)   /* Soft Reset */
#define CTRL_IRQ_EN_BIT     (UINT32_C(1) << 2)   /* Global IRQ Enable */
#define CTRL_MODE_MASK      (UINT32_C(0x3) << 4) /* Mode[5:4] */

/* STATUS (W1C - Write 1 to Clear) */
#define STATUS_DONE_BIT     (UINT32_C(1) << 0)   /* Operation Complete */
#define STATUS_ERR_BIT      (UINT32_C(1) << 1)   /* Error Flag */
#define STATUS_BUSY_BIT     (UINT32_C(1) << 2)   /* Busy (Read-Only) */
#define STATUS_W1C_BITS     (STATUS_DONE_BIT | STATUS_ERR_BIT) /* Clearable bits */

/* IRQ_MASK */
#define IRQ_MASK_DONE_BIT   (UINT32_C(1) << 0)
#define IRQ_MASK_ERR_BIT    (UINT32_C(1) << 1)

/* Type-safe Register Block */
typedef struct __attribute__((aligned(4), packed)) {
    volatile uint32_t CTRL;        /* 0x00: Control Register */
    volatile uint32_t STATUS;      /* 0x04: Status Register (W1C) */
    volatile uint32_t DATA;        /* 0x08: Data Register */
    volatile uint32_t IRQ_MASK;    /* 0x0C: Interrupt Mask Register */
} peripheral_regs_t;

/* Compile-time verification of register layout */
static_assert(sizeof(peripheral_regs_t) == 16, "Register block size mismatch");
static_assert(offsetof(peripheral_regs_t, CTRL)     == REG_CTRL_OFFSET,     "CTRL offset mismatch");
static_assert(offsetof(peripheral_regs_t, STATUS)   == REG_STATUS_OFFSET,   "STATUS offset mismatch");
static_assert(offsetof(peripheral_regs_t, DATA)     == REG_DATA_OFFSET,     "DATA offset mismatch");
static_assert(offsetof(peripheral_regs_t, IRQ_MASK) == REG_IRQ_MASK_OFFSET, "IRQ_MASK offset mismatch");

/* ============================================================================
 * MMIO Accessors (Strict Aliasing & Alignment Safe)
 * ============================================================================ */

static inline uint32_t mmio_read32(const volatile uint32_t *addr) {
    assert(addr != NULL);
    assert(((uintptr_t)addr & 0x3) == 0); /* Enforce 4-byte alignment */
    uint32_t val = *addr;
    compiler_barrier(); /* Prevent load hoisting */
    return val;
}

static inline void mmio_write32(volatile uint32_t *addr, uint32_t val) {
    assert(addr != NULL);
    assert(((uintptr_t)addr & 0x3) == 0); /* Enforce 4-byte alignment */
    compiler_barrier(); /* Prevent store sinking */
    *addr = val;
    dmb_ish(); /* Ensure write reaches peripheral before subsequent ops */
}

/* ============================================================================
 * Driver Context & State Machine
 * ============================================================================ */

typedef enum {
    DRV_STATE_UNINIT = 0,
    DRV_STATE_IDLE,
    DRV_STATE_BUSY,
    DRV_STATE_ERROR
} drv_state_t;

typedef struct {
    peripheral_regs_t *regs;
    drv_state_t state;
    uint32_t last_status;
} peripheral_drv_t;

/* ============================================================================
 * Core Driver API
 * ============================================================================ */

/**
 * @brief Initialize driver context and verify hardware presence.
 * @param drv Driver context pointer.
 * @return true on success, false on alignment/hardware fault.
 */
bool peripheral_init(peripheral_drv_t *drv) {
    if (drv == NULL) return false;

    /* Map physical address to kernel virtual address (Identity mapped in bare metal) */
    drv->regs = (peripheral_regs_t *)PERIPH_BASE_ADDR;

    /* Verify alignment of peripheral base */
    if (((uintptr_t)drv->regs & 0xF) != 0) return false; /* 16-byte aligned preferred */

    /* Read ID/Status to verify bus access (side-effect free read) */
    uint32_t status = mmio_read32(&drv->regs->STATUS);
    (void)status; /* Suppress unused warning if asserts disabled */

    drv->state = DRV_STATE_IDLE;
    drv->last_status = 0;

    /* Default: Disable IRQs, Disable Peripheral */
    mmio_write32(&drv->regs->IRQ_MASK, 0);
    mmio_write32(&drv->regs->CTRL, 0);

    return true;
}

/**
 * @brief Safely modify CTRL register using Read-Modify-Write with barriers.
 */
void peripheral_ctrl_set_bits(peripheral_drv_t *drv, uint32_t mask) {
    assert(drv && drv->regs);
