#include <stdint.h>
#include <stdbool.h>
#include <stddef.h>
#include <assert.h>

/* ============================================================================
 * Platform Configuration & Compilation Guards
 * ============================================================================
 * Allows compilation on host (x86_64) for static analysis/unit testing by
 * mapping the peripheral base to a local static buffer. On target (ARMv8-A),
 * the hardcoded physical address is used.
 */
#ifndef PERIPHERAL_BASE_ADDR
    #if defined(__aarch64__) || defined(__ARM_ARCH_8A__)
        #define PERIPHERAL_BASE_ADDR (0x40001000UL)
    #else
        /* Host simulation buffer: 64-byte aligned to satisfy burst constraints */
        static uint8_t sim_mem[4096] __attribute__((aligned(64))) = {0};
        #define PERIPHERAL_BASE_ADDR ((uintptr_t)sim_mem)
    #endif
#endif

/* ============================================================================
 * Register Map Definition (ARMv8-A MMIO)
 * ============================================================================
 * Base: 0x4000_1000
 * Offsets:
 *   0x00: CTRL       (RW)
 *   0x04: STATUS     (R,  W1C - Write 1 to Clear)
 *   0x08: DATA       (RW) - FIFO Port, 64-byte burst capable
 *   0x0C: IRQ_MASK   (RW)
 * ============================================================================
 */
typedef struct peripheral_regs {
    volatile uint32_t CTRL;        /* 0x00: Control Register */
