/* Blocking Polled Transfer (Example Usage Pattern) */
periph_status_t peripheral_transfer_polled(const uint32_t *tx_buf, uint32_t *rx_buf, size_t word_count) {
    if (word_count == 0) return PERIPH_OK;

    /* Check TX FIFO Ready (assume STATUS bit 1 = TX_READY) */
    const uint32_t TX_READY = BIT_MASK(1);
    const uint32_t RX_VALID = BIT_MASK(2);
    const uint32_t ERR_FLAG = BIT_MASK(31);

    size_t tx_idx = 0;
    size_t rx_idx = 0;

    while (tx_idx < word_count || rx_idx < word_count) {
        uint32_t status = status_read();

        if (status & ERR_FLAG) {
            status_clear_bits(ERR_FLAG);
            return PERIPH_ERR_BUSY; /* Or specific error code */
        }

        /* Handle TX Burst if possible */
        if (tx_idx < word_count && (status & TX_READY)) {
            size_t remaining = word_count - tx_idx;
            size_t burst_len = (remaining >= 16) ? 16 : remaining; /* Max burst 16 words */

