            if (burst_len == 16 && (((uintptr_t)(tx_buf + tx_idx) & 63U) == 0U)) {
                if (!data_write_burst(tx_buf + tx_idx, 16)) return PERIPH_ERR_ALIGNMENT;
                tx_idx += 16;
            } else {
                /* Single word fallback */
                data_write(tx_buf[tx_idx++]);
            }
        }

        /* Handle RX Burst if possible */
        if (rx_idx < word_count && (status & RX_VALID)) {
            size_t remaining = word_count - rx_idx;
            size_t burst_len = (remaining >= 16) ? 16 : remaining;

            if (burst_len == 16 && (((uintptr_t)(rx_buf + rx_idx) & 63U) == 0U)) {
                if (!data_read_burst(rx_buf + rx_idx, 16)) return PERIPH_ERR_ALIGNMENT;
                rx_idx += 16;
            } else {
                rx_buf[rx_idx++] = data_read();
            }
        }

        /* Prevent busy-spin lockup if hardware stalls (architectural timeout) */
        __builtin_arm_nop(); /* Yield / WFE hint could go here */
    }

    return PERIPH_OK;
}

