void test_edge_cases() {
    // Empty range
    TimeRange empty{RationalTime{0, 1}, RationalTime{0, 1}};
    assert(empty.duration.numerator == 0);
    assert(!empty.contains(RationalTime{0, 1}));

    // Negative offset in time range
    TimeRange neg_range{RationalTime{-10, 1}, RationalTime{20, 1}};
    assert(neg_range.start_time.numerator == -10);
    assert(neg_range.end_time_exclusive() == RationalTime{10, 1});
    assert(neg_range.contains(RationalTime{0, 1}));
    assert(!neg_range.contains(RationalTime{-10, 1}));  // Start is inclusive
    assert(neg_range.contains(RationalTime{-9, 1}));

    // Exact boundary overlap
    TimeRange a{RationalTime{0, 1}, RationalTime{10, 1}};
    TimeRange b{RationalTime{10, 1}, RationalTime{10, 1}};
    assert(!a.overlaps(b));
    assert(!b.overlaps(a));
    assert(!a.intersection(b).has_value());

